/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    super();
    if(element.args().dataset() == tableNum(CustTable))
    {
        callCustTable = element.args().record();
    }
    priceDate  = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_set">_set</param>
/// <param name = "_itemId">_itemId</param>
/// <returns>itemId</returns>
edit itemId editItemId(boolean _set , ItemId _itemId)
{
    if(_set)
    {
        inventTable = InventTable::find(_itemId);
        CustTable_ds.executeQuery();

        select firstonly custrackDiscItems
            where custrackDiscItems.CustAccount ==  custTable.AccountNum
               && custrackDiscItems.ItemId      == _itemId;

        select firstonly chainRackDiscItems
            where chainRackDiscItems.smmChainId == CustTable.CompanyChainId
               && chainRackDiscItems.ItemId     == _itemId;

        select firstonly priceSurchargesValues
            where priceSurchargesValues.AVAPriceSurchargeCode == inventTable.AVAPriceSurchargeCode
               && priceSurchargesValues.ValidFromDate <=  DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
               && (priceSurchargesValues.ValidToDate == dateNull() || priceSurchargesValues.ValidToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())) ;
    }
    return inventTable.itemId;
}

