/// <param name = "_priceDate">_priceDate</param>
/// <returns>priceDate</returns>
edit KCS_PriceDate editPriceDate(boolean _set , KCS_PriceDate _priceDate)
{
    if(_set)
    {
        priceDate = _priceDate;
        custTable_ds.executeQuery();
    }
    return priceDate;
}

