/// <summary>
/// desigend from AVA
/// </summary>
/// <returns>search</returns>
public Percent custLineDiscGrpPctSearch()
{
    Percent     lineDiscPct;

    PriceDiscTable     priceDiscTable = AVAPriceDiscGroupSearch::searchDiscCodeRelation(PriceDiscPartyCodeType::GroupId,
                                                                              CustTable.LineDisc,
                                                                              PriceDiscProductCodeType::Table,
                                                                              inventTable.ItemId,
                                                                              priceDate != dateNull() ? priceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                              PriceType::LineDiscSales);

    if  (!priceDiscTable.RecId)
    {
        priceDiscTable = AVAPriceDiscGroupSearch::searchDiscCodeRelation(PriceDiscPartyCodeType::GroupId,
                                                                              CustTable.LineDisc,
                                                                              PriceDiscProductCodeType::GroupId,
                                                                              InventTableModule::find(inventTable.ItemId,ModuleInventPurchSales::Sales).LineDisc,
                                                                              priceDate != dateNull() ? priceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                              PriceType::LineDiscSales);
    }

    lineDiscPct = priceDiscTable.Percent1;
    return lineDiscPct;
}

