/// <summary>
/// designed from AVA
/// </summary>
/// <returns>salesPrice</returns>
display public SalesPrice calcPriceGroupPrice()
{

    calcsalesPrice = AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,CustTable.PriceGroup,'',inventTable.ItemId, priceDate != dateNull() ? priceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),CustTable.Currency).Amount;

    if (calcsalesPrice == 0)
    {
        calcsalesPrice = AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,smmBusRelChainGroup.AVAPriceGroupId,'',inventTable.ItemId, priceDate != dateNull() ? priceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),CustTable.Currency).Amount;
    }
    return calcsalesPrice;
}

