 }

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>str</returns>
display public String20 calcLineDiscAllPct()
{
    calcLineDiscAllPct = 0;
    if (calcLineDiscGrpPct == 0)
    {
        calcLineDiscAllPct = this.custLineDiscAllPctSearch();
        if (calcLineDiscAllPct == 0)
        {
            calcLineDiscAllPct =  this.chainLineDiscAllPctSearch();
        }
    }

    return calcLineDiscAllPct ? num2Str(calcLineDiscAllPct,-1,-1,-1,-1) + '%' : '';
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>SAlesPrice</returns>
display public SalesPrice   calcDiscountedPrice()
{
    Percent             discount;

    discount = calcLineDiscGrpPct ? calcLineDiscGrpPct : calcLineDiscAllPct;

    calcDiscountedPrice = discount != 0 ? calcSalesPrice * (100-discount) / 100 : calcSalesPrice;

    return calcDiscountedPrice;
}

