/// <summary>
/// designed from AVA
/// </summary>
/// <returns>SAlesPrice</returns>
display public SalesPrice calcBestPrice()
{

    calcBestPrice = calcDiscountedPrice;
    calcBestPrice = calcNettoPG1Price > 0 ? (calcBestPrice > 0  ? min( calcbestPrice, calcNettoPG1Price) : calcNettoPG1Price) :   calcbestPrice;
    calcbestPrice = calcNettoPG2Price > 0 ? (calcbestPrice > 0  ? min( calcbestPrice, calcNettoPG2Price) : calcNettoPG2Price) :   calcbestPrice;
    return calcBestPrice;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>str</returns>
display public String20 rankCustDiscQtyStr()
{
    EcoResProductRecId              ecoResProduct = inventTable.Product;
    UnitOfMeasure                   unitOfMeasure;
    UnitOfMeasureConversion         conversion;
    Qty                             rackQty;


    select firstonly conversion where conversion.Product == ecoResProduct
        join unitOfMeasure where unitOfMeasure.RecId == conversion.FromUnitOfMeasure
        && unitOfMeasure.AVARackDiscAble == NoYes::Yes;
    rackQty = conversion.Factor;
    return  rackQty != 0 ?  num2Str(rackQty,-1,0,-1,-1) : '';
}

